using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Automation;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using RingTimer;
class WorkRestInteractionTests {
 static int checks;static string log;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;File.AppendAllText(log,"PASS "+name+Environment.NewLine);}
 static bool Near(double a,double b){return Math.Abs(a-b)<.1;}
 static IEnumerable<T> All<T>(DependencyObject n) where T:DependencyObject{if(n is T)yield return (T)n;for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++)foreach(var x in All<T>(VisualTreeHelper.GetChild(n,i)))yield return x;}
 static void Pump(int ms=30){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 static int InkPixels(SlidingRail rail,int index,Brush ink){var color=((SolidColorBrush)ink).Color;var image=new RenderTargetBitmap(278,34,96,96,PixelFormats.Pbgra32);image.Render(rail);var pixels=new byte[278*34*4];image.CopyPixels(pixels,278*4,0);int count=0;double step=272.0/3;for(int y=8;y<26;y++)for(int x=(int)(3+index*step+15);x<(int)(3+(index+1)*step-15);x++){int p=(y*278+x)*4;if(Math.Abs(pixels[p]-color.B)<15&&Math.Abs(pixels[p+1]-color.G)<15&&Math.Abs(pixels[p+2]-color.R)<15)count++;}return count;}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);log=Path.Combine(args[0],"result.txt");File.WriteAllText(log,"");var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window window=null;
 try{Theme.Apply(true,null,null,null);Theme.ApplyGlobalResources(app);var stack=new StackPanel();var rail=new SlidingRail("日历","总量","分段"){Width=278};stack.Children.Add(rail);var button=Theme.Button("测试按键",true);stack.Children.Add(button);window=new Window{Content=stack,Width=320,Height=600,Left=-2200,Top=0,ShowInTaskbar=false};window.Show();Pump();double step=(278-6)/3.0;int changes=0;rail.Changed+=n=>changes++;
 rail.BeginGesture(16);rail.AdvanceFrame(.016);Check(Near(rail.ThumbPosition,0),"grabbing left edge does not jump");rail.MoveGesture(16+step*.55);rail.AdvanceFrame(.016);Check(rail.ThumbPosition>0&&rail.ThumbPosition<step*.55&&changes==0,"drag approaches pointer with light damping without rebuilding statistics");rail.EndGesture(true);double start=rail.ThumbPosition;rail.AdvanceFrame(.016);Check(rail.Selected==1&&changes==1&&rail.ThumbPosition>start&&rail.ThumbPosition<step,"release settles continuously to nearest tab");rail.AdvanceFrame(.3);Check(Near(rail.ThumbPosition,step),"rail settles at exact destination");
 rail.BeginGesture(step+13);rail.MoveGesture(-100);rail.AdvanceFrame(.016);Check(rail.ThumbPosition>=0&&rail.ThumbPosition<step,"drag remains inside track");rail.EndGesture(false);rail.AdvanceFrame(.3);Check(rail.Selected==1&&Near(rail.ThumbPosition,step)&&changes==1,"capture cancellation restores selected tab");
 rail.BeginGesture(270);double beforePress=rail.ThumbPosition;rail.AdvanceFrame(.016);Check(rail.ThumbPosition>beforePress&&rail.ThumbPosition<2*step,"press at remote tab slides from previous position");rail.EndGesture(true);rail.AdvanceFrame(.3);Check(rail.Selected==2&&changes==2,"click at distant tab works without drag");rail.BeginGesture(260);rail.MoveGesture(190);rail.AdvanceFrame(.016);rail.IsEnabled=false;rail.AdvanceFrame(.3);Check(!rail.IsInteracting&&rail.Selected==2,"disabling mid-gesture cancels safely");rail.IsEnabled=true;
 rail.CaptureMouse();rail.BeginGesture(250);rail.EndGesture(false);Check(!rail.IsMouseCaptured,"cancel releases native mouse capture");rail.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(rail),0,Key.Home){RoutedEvent=Keyboard.PreviewKeyDownEvent});rail.AdvanceFrame(.3);Check(rail.Selected==0,"keyboard Home selects calendar");
 rail.BeginGesture(270);for(int i=0;i<3;i++)rail.AdvanceFrame(1.0/30);double slow=rail.ThumbPosition;rail.EndGesture(false);rail.AdvanceFrame(.3);rail.BeginGesture(270);for(int i=0;i<12;i++)rail.AdvanceFrame(1.0/120);Check(Near(rail.ThumbPosition,slow),"damping follows elapsed time consistently at 30 and 120 fps");rail.AdvanceFrame(.25);Check(Math.Abs(rail.ThumbPosition-2*step)<.5,"held pointer converges without overshoot");rail.EndGesture(false);rail.AdvanceFrame(.3);foreach(bool dark in new[]{true,false}){Theme.Apply(dark,null,null,null);rail.Select(0,false);rail.AdvanceFrame(.3);rail.BeginGesture(270);rail.AdvanceFrame(.5);Check(rail.Selected==0&&InkPixels(rail,2,Theme.PrimaryText)>8,"covered text changes color before release: "+dark);Check(InkPixels(rail,0,Theme.Muted)>8,"uncovered text restores muted color while held: "+dark);Theme.Snapshot(rail,Path.Combine(args[0],"held-contrast-"+dark+".png"),2);rail.EndGesture(false);rail.AdvanceFrame(.3);Check(InkPixels(rail,0,Theme.PrimaryText)>8,"cancel restores contrast at original thumb: "+dark);rail.Select(2,true);Check(InkPixels(rail,0,Theme.PrimaryText)>8,"release selection does not recolor ahead of thumb: "+dark);rail.AdvanceFrame(.06);Check(InkPixels(rail,1,Theme.PrimaryText)>8,"text follows thumb through middle tab during settling: "+dark);Theme.Snapshot(rail,Path.Combine(args[0],"settling-contrast-"+dark+".png"),2);rail.AdvanceFrame(.3);Check(InkPixels(rail,2,Theme.PrimaryText)>8,"destination contrast remains correct: "+dark);}Theme.Apply(true,null,null,null);button.ApplyTemplate();var face=(FrameworkElement)button.Template.FindName("surface",button);var depth=(FrameworkElement)button.Template.FindName("depth",button);Check(depth!=null,"button has inset shadow surface");
 button.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left){RoutedEvent=UIElement.PreviewMouseLeftButtonDownEvent});Pump(140);var scale=face.RenderTransform as ScaleTransform;Check(scale!=null&&scale.ScaleX<.97,"press physically compresses button");button.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,0,MouseButton.Left){RoutedEvent=UIElement.PreviewMouseLeftButtonUpEvent});double peak=scale.ScaleX;EventHandler sample=(sender,eventArgs)=>peak=Math.Max(peak,scale.ScaleX);CompositionTarget.Rendering+=sample;try{Pump(410);}finally{CompositionTarget.Rendering-=sample;}Check(peak>1,"release produces slight overshoot");Check(Near(scale.ScaleX,1),"release returns to full size");
 var now=new DateTime(2026,11,1,10,0,0,DateTimeKind.Utc);var engine=new TimerEngine(new TimerState(),()=>now);Check(engine.State.Groups==1,"default group count is one");var timerPanel=new TimerPanel(engine,()=>{});stack.Children.Clear();stack.Children.Add(timerPanel);Pump();Check(All<CycleRing>(timerPanel).Count()==1&&!All<CheckBox>(timerPanel).Any(),"timer uses ring and no sound toggle");
 engine.StartCycle(5,2,2);now=now.AddSeconds(14);engine.Tick();timerPanel.PaintState();Pump();Check(All<TextBlock>(timerPanel).Any(t=>t.Text=="第 2 / 2 组")&&All<TextBlock>(timerPanel).Any(t=>t.Text=="00:00"),"finished batch shows final group and zero remaining");Check(All<TextBlock>(timerPanel).Any(t=>t.Text=="已停下，等待再次开始"),"finished batch explicitly waits");Theme.Snapshot(window,Path.Combine(args[0],"finished.png"),1.5);
 var store=new StatsStore(null,TimeZoneInfo.Utc);store.Collect(engine.State);var bucket=store.Day(now.Date);Check(bucket.WorkSeconds==10&&bucket.RestSeconds==4&&bucket.WorkSessions==2&&bucket.RestSessions==2,"work and rest totals and counts agree");var panel=new StatsPanel(store,()=>now.Date);stack.Children.Clear();stack.Children.Add(panel);Pump();
 foreach(string view in new[]{"calendar","total","sessions"}){panel.SelectView(view);Pump();Check(!All<TextBlock>(panel).Any(t=>t.Text.Contains("目标")||t.Text.Contains("未分类")),"only work and rest labels in "+view);Theme.Snapshot(window,Path.Combine(args[0],view+".png"),2);}
 Check(All<TextBlock>(panel).Any(t=>t.Text==StatsPanel.Duration(14)+" · 4 次"),"mixed sessions header counts both work and rest");var activeRail=All<SlidingRail>(panel).Single();var currentBody=All<ContentControl>(panel).First(c=>!(c is UserControl)&&c.Content is StackPanel);var old=currentBody.Content;activeRail.BeginGesture(250);engine.StartCycle(60,10,1);now=now.AddSeconds(8);store.UpdateLive(engine.CurrentSession());Pump();Check(ReferenceEquals(old,currentBody.Content),"live refresh defers while rail is dragged");activeRail.EndGesture(false);Pump();Check(!ReferenceEquals(old,currentBody.Content),"deferred refresh applies after rail gesture");
 File.AppendAllText(log,checks+" interaction checks passed");return 0;
 }catch(Exception ex){File.AppendAllText(log,"FAIL "+ex);return 1;}finally{if(window!=null)window.Close();app.Shutdown();}}
}
